import React, { useEffect, useState } from "react";
import EventCard from "./events/EventCard";
import EventDetails from "./events/EventDetails";
import Chatbot from "./Chatbot";   // ✅ Chatbot added back

export default function Home() {
  const [events, setEvents] = useState([]);
  const [selected, setSelected] = useState(null);

  useEffect(() => {
    fetch((process.env.REACT_APP_API || "http://localhost:4000") + "/api/dashboard/events")
      .then((r) => r.json())
      .then(setEvents)
      .catch(console.error);
  }, []);

  return (
    <div id="home-section" className="home-page">

      {/* 🔵 HERO BANNER */}
      <section
        className="hero"
        style={{
          backgroundImage:
            "url('')",
          backgroundSize: "cover",
          backgroundPosition: "center",
          height: "70vh",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: "white",
          textShadow: "0 0 8px black",
        }}
      >
        <h1>Welcome to HelpingHands</h1>
      </section>

      {/* 🔵 ABOUT US SECTION */}
      <section id="about-section" className="section">
        <h2>About Us</h2>
        <p>
          We are a dedicated NGO working towards education, women empowerment,
          healthcare support, and community upliftment.
        </p>

        <img
          src=""
          alt="NGO Work"
          style={{
            width: "100%",
            borderRadius: 10,
            marginTop: 16,
          }}
        />
      </section>

      {/* 🔵 EVENTS SECTION */}
      <section id="events-section" className="section">
        <h2>Upcoming Events</h2>

        <div className="cards">
          {events.slice(0, 3).map((ev) => (
            <EventCard
              key={ev.id}
              event={ev}
              onClick={() => setSelected(ev)}
            />
          ))}
        </div>

        {selected && (
          <div style={{ marginTop: 16 }}>
            <EventDetails event={selected} onClose={() => setSelected(null)} />
          </div>
        )}
      </section>

      {/* 🔵 CONTACT US SECTION */}
      <section id="contact-section" className="section">
        <h2>Contact Us</h2>

        <p><strong>Phone:</strong> +91 98765 43210</p>
        <p><strong>Email:</strong> support@ngoportal.org</p>

        <img
          src="https://www.unesco.org/sites/default/files/styles/relative_crop_3x2_960x640/public/2023-12/contact_us.jpg"
          alt="Contact"
          style={{
            width: "100%",
            borderRadius: 10,
            marginTop: 16,
          }}
        />
      </section>

      {/* 🔵 CHATBOT ALWAYS ON HOME PAGE */}
      <Chatbot />   {/* ✅ Restored */}
    </div>
  );
}
